const r = $input.first().json || {};
if (!r.resolved_area) { return [{ json: { response: 'Не нашёл активную травму с таким id — уточни у клиента, какую именно закрыть (id травм показаны в профиле).' } }]; }
let lifted = r.lifted;
if (typeof lifted === 'string') { try { lifted = JSON.parse(lifted); } catch (e) { lifted = []; } }
if (!Array.isArray(lifted)) lifted = [];
let s = 'Травма «' + r.resolved_area + '» отмечена как закрытая.';
s += lifted.length ? (' Автоматически сняты связанные ограничения: ' + lifted.join(', ') + '. Эти нагрузки снова разрешены.') : ' Связанных активных ограничений не было.';
return [{ json: { response: s } }];
